 const RawResult: FC<{
 	value: unknown;
 	viewState?: ViewState;
 	onViewStateChange?: ViewStateChange;
 }> = ({ value, viewState, onViewStateChange }) => {
 	const [copyStatus, setCopyStatus] = useState<"idle" | "copied" | "failed">(
 		"idle",
 	);
 	const json = stringify(value);
 	return (
 		<PersistentDetails
 			summary="Raw result"
 			stateKey="details.raw.open"
 			viewState={viewState}
 			onViewStateChange={onViewStateChange}
 			className={cn(FILLED_BOX, "px-3 py-2 text-xs")}
 		>
 			<div className="mt-2">
 				<div className="mb-2 flex justify-end">
 					<Button
 						type="button"
 						variant="outline"
 						size="sm"
 						onClick={() => {
 							if (!navigator.clipboard) {
 								setCopyStatus("failed");
 								return;
 							}
 							void navigator.clipboard
 								.writeText(json)
 								.then(() => setCopyStatus("copied"))
 								.catch(() => setCopyStatus("failed"));
 						}}
 					>
 						{copyStatus === "copied"
 							? "Copied"
 							: copyStatus === "failed"
 								? "Copy failed"
 								: "Copy JSON"}
 					</Button>
 				</div>
 				<pre className="max-h-80 overflow-auto whitespace-pre-wrap rounded-md border border-border/70 bg-background/40 p-2">
 					{json}
 				</pre>
 			</div>
 		</PersistentDetails>
 	);
 };

