 22	/** Shared iframe-side runtime for every Lobu MCP App bundle. */
 23	
 24	type ToolArgs = Record<string, unknown>;
 25	type ViewStateValue = boolean | number | string;
 26	type McpAppViewState = Record<string, ViewStateValue>;
 27	
 28	interface McpAppApi<T> {
 29		/** Server-authored LobuViewV1 from the originating tool result. */
 30		data: T | null;
 31		/** True when the host card is known but its persisted result no longer exists. */
 32		resultUnavailable: boolean;
 33		/** Originating MCP tool name, supplied by the standard host context. */
 34		toolName: string | null;
 35		/** Small restored pagination/disclosure state for this exact result card. */
 36		viewState: McpAppViewState;
 37		setViewState: (key: string, value: ViewStateValue) => void;
 38		/** Ask the host to broker a standard MCP `tools/call`. */
 39		callTool: (name: string, args: ToolArgs) => Promise<void>;
 40		/** Ask the host to open an external URL via `ui/open-link`. */
 41		openLink: (href: string) => Promise<void>;
 42		/** Latest app-initiated tool result; `seq` bumps so effects react to retries. */
 43		lastResult: { isError: boolean; seq: number } | null;
 44		/** True only inside Lobu's same-origin SPA parent, never in an external host. */
 45		allowSpaHostedViews: boolean;
 46	}
 47	
 48	const McpAppContext = createContext<McpAppApi<unknown>>({
 49		data: null,
 50		resultUnavailable: false,
 51		toolName: null,
 52		viewState: {},
 53		setViewState: () => {},
 54		callTool: async () => {},
 55		openLink: async () => {},
 56		lastResult: null,
 57		allowSpaHostedViews: false,
 58	});
