 60	/** Typed accessor for the host bridge inside a bundle's card component. */
 61	export function useMcpApp<T>(): McpAppApi<T> {
 62		return useContext(McpAppContext) as McpAppApi<T>;
 63	}
 64	
 65	const isEmbedded = window.parent !== window;
 66	const OPENAI_SET_GLOBALS_EVENT = "openai:set_globals";
 67	
 68	type OpenAiCompatWindow = Window & { openai?: unknown };
 69	type OpenAiSetGlobalsEvent = CustomEvent<{ globals?: unknown }>;
 70	
 71	function openAiCompatTargets(): OpenAiCompatWindow[] {
 72		const ownWindow = window as OpenAiCompatWindow;
 73		if (!isEmbedded) return [ownWindow];
 74		try {
 75			if (window.parent.location.origin === window.location.origin) {
 76				return [ownWindow, window.parent as OpenAiCompatWindow];
 77			}
 78		} catch {
 79			// A cross-origin parent is the standard portable MCP Apps topology.
 80		}
 81		return [ownWindow];
 82	}
 83	
 84	function currentOpenAiGlobals(targets = openAiCompatTargets()): unknown {
 85		let fallback: unknown;
 86		let metadataFallback: unknown;
 87		let widgetStateFallback: unknown;
 88		for (const target of targets) {
 89			const candidate = target.openai;
 90			if (candidate === undefined) continue;
 91			fallback ??= candidate;
 92			if (
 93				isStructuredObject(candidate) &&
 94				Object.hasOwn(candidate, "toolOutput")
 95			) {
 96				return candidate;
 97			}
 98			if (
 99				isStructuredObject(candidate) &&
100				readOpenAiCompatSnapshot(candidate).data !== undefined
101			) {
102				widgetStateFallback ??= candidate;
103			}
104			if (
105				isStructuredObject(candidate) &&
106				Object.hasOwn(candidate, "toolResponseMetadata")
107			) {
108				metadataFallback ??= candidate;
109			}
110		}
111		return widgetStateFallback ?? metadataFallback ?? fallback;
112	}
113	
114	function persistOpenAiData<T>(
115		targets: OpenAiCompatWindow[],
116		data: T | null,
117		resultIdentity: string | null = null,
118	): void {
119		for (const target of targets) {
120			if (persistOpenAiViewSnapshot(target.openai, data, resultIdentity)) return;
121		}
122	}
123	
124	function hasSameOriginParent(): boolean {
125		if (!isEmbedded) return true;
126		try {
127			return window.parent.location.origin === window.location.origin;
128		} catch {
129			return false;
130		}
131	}
132	
133	function isStructuredObject(value: unknown): value is Record<string, unknown> {
134		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
135	}
136	
137	function hasResultData(value: unknown): value is Record<string, unknown> {
138		return isStructuredObject(value) && Object.keys(value).length > 0;
139	}
140	
141	function toolInfoFromHostContext(value: unknown): {
142		id: string | number;
143		name: string;
144	} | null {
145		if (!isStructuredObject(value) || !isStructuredObject(value.toolInfo))
146			return null;
147		const id = value.toolInfo.id;
148		const tool = value.toolInfo.tool;
149		if (
150			(typeof id !== "string" && typeof id !== "number") ||
151			!isStructuredObject(tool) ||
152			typeof tool.name !== "string"
153		) {
154			return null;
155		}
156		return { id, name: tool.name };
157	}
158	
159	function hostIdentityKey(id: string | number, name: string): string {
160		return JSON.stringify([id, name]);
161	}
162	
163	function snapshotCapabilityFromMeta(value: unknown): string | null | undefined {
164		if (
165			!isStructuredObject(value) ||
166			!Object.hasOwn(value, "lobu/mcp-app-snapshot-capability")
167		)
168			return undefined;
169		const capability = value["lobu/mcp-app-snapshot-capability"];
170		if (typeof capability !== "string") return null;
171		const normalized = capability.trim();
172		return normalized && normalized.length <= 512 ? normalized : null;
173	}
174	
175	function restoredViewState(value: unknown): McpAppViewState {
176		if (!isStructuredObject(value)) return {};
177		return Object.fromEntries(
178			Object.entries(value).filter(
179				(entry): entry is [string, ViewStateValue] =>
180					typeof entry[1] === "boolean" ||
181					typeof entry[1] === "string" ||
182					(typeof entry[1] === "number" && Number.isFinite(entry[1])),
183			),
184		);
185	}
186	
187	function sameViewState(left: McpAppViewState, right: McpAppViewState): boolean {
188		const leftKeys = Object.keys(left);
189		const rightKeys = Object.keys(right);
190		return (
191			leftKeys.length === rightKeys.length &&
192			leftKeys.every((key) => left[key] === right[key])
193		);
194	}
195	
196	function resultDataFingerprint(value: unknown): string | null {
197		try {
198			const displaySafeValue = displaySafeOpenAiSnapshotData(value);
199			return (
200				JSON.stringify(displaySafeValue, (_key, nested) =>
201					isStructuredObject(nested)
202						? Object.fromEntries(
203								Object.entries(nested).sort(([left], [right]) =>
204									left.localeCompare(right),
205								),
206							)
207						: nested,
208				) ?? null
209			);
210		} catch {
211			return null;
212		}
213	}
214	
215	function applyTheme(theme: "light" | "dark" | undefined): void {
216		const dark = theme
217			? theme === "dark"
218			: window.matchMedia("(prefers-color-scheme: dark)").matches;
219		document.documentElement.classList.toggle("dark", dark);
220	}
