234			: null;
235		const [data, setData] = useState<T | null>(
236			isEmbedded ? initialData : devMock,
237		);
238		const [resultUnavailable, setResultUnavailable] = useState(false);
239		const [toolName, setToolName] = useState<string | null>(null);
240		const [viewState, setViewStateValue] = useState<McpAppViewState>({});
241		const [lastResult, setLastResult] = useState<{
242			isError: boolean;
243			seq: number;
