248		);
249		const hasLiveToolOutput = useRef(false);
250		const hasAuthoritativeResultData = useRef(false);
251		const hasCurrentLifetimeToolResult = useRef(false);
252		const hasData = useRef(data !== null);
253		const resultExplicitlyCleared = useRef(false);
254		const hasAuthoritativeResultAbsence = useRef(false);
255		const authoritativeDataRevision = useRef(0);
256		const resultGeneration = useRef(0);
257		const toolCallId = useRef<string | number | null>(null);
258		const toolCallName = useRef<string | null>(null);
259		const supersededHostIdentity = useRef<string | null>(null);
260		const hasDetachedAppResult = useRef(
