542								...(capability === null && name ? { tool_name: name } : {}),
543								...(capability ? { snapshot_capability: capability } : {}),
544							},
545						});
546						if (
547							snapshotCapability.current !== capability ||
548							toolCallId.current !== id ||
549							toolCallName.current !== name ||
550							resultGeneration.current !== resultGenerationAtStart
551						) {
552							return false;
553						}
554						if (!isStructuredObject(result.structuredContent)) {
555							return false;
556						}
557						const restored = result.structuredContent;
558						if (restored.found === false) {
559							snapshotRestoreCompleted.current.add(restoreKey);
560							if (capability !== null && id !== null) {
561								// A capability is the fresh result identity. If it no longer resolves,
562								// do not fall back to a host id that may have been reused for an older
