564								detachActiveHostIdentity();
565							}
566							if (!hasAuthoritativeResultData.current) {
567								// Widget state is only a display cache. Once the server confirms
568								// that its scoped snapshot is gone, do not leave that historical
569								// card's identity or UI state attached to the next result. A live
570								// result delivered during this restore remains authoritative.
571								resetResultViewState();
572								hasAuthoritativeResultAbsence.current = true;
573								hasData.current = false;
574								displayedDataFingerprint.current = null;
575								displayedData.current = null;
576								displayedResultIdentity.current = null;
577								setData(null);
578								setResultUnavailable(true);
579								persistOpenAiData(compatTargets, null, null);
580							}
581							rejectActiveSnapshotCapability(capability);
582							return true;
583						}
584						if (restored.found !== true || !hasResultData(restored.data)) {
585							return false;
586						}
587						const nextData = restored.data as T;
588						const nextDataFingerprint = resultDataFingerprint(nextData);
589						if (
590							capability === null &&
591							allowDataPresent &&
592							hasAuthoritativeResultData.current &&
593							displayedDataFingerprint.current !== nextDataFingerprint
594						) {
595							// A host can expose the previous card's toolInfo alongside fresh,
596							// unpaired compatibility output. An id-only restore may contribute UI
597							// state only when its persisted result matches the visible result.
598							detachActiveHostIdentity();
599							return false;
600						}
601						if (
602							authoritativeDataRevision.current !==
603								authoritativeDataRevisionAtStart &&
604							displayedDataFingerprint.current !== nextDataFingerprint
605						) {
606							rejectActiveSnapshotCapability(capability);
607							return false;
608						}
609						const replacesUnkeyedResult =
610							capability !== null &&
611							capabilityBoundaryCandidate.current === capability &&
612							hasData.current &&
613							displayedDataFingerprint.current !== nextDataFingerprint;
614						if (replacesUnkeyedResult) resetForCapabilityResult(capability);
615						snapshotRestoreCompleted.current.add(restoreKey);
616						const restoredState = restoredViewState(restored.view_state);
617						const currentState = viewStateRef.current;
618						const changedDuringRestore =
619							viewStateRevision.current !== viewStateRevisionAtStart;
620						const startsFreshResult =
621							capability !== null &&
622							freshRestoreCapability.current === capability;
623						const hasLocalViewState = startsFreshResult
624							? viewStateRevision.current > 0
625							: viewStateRevisionAtStart > 0 || changedDuringRestore;
626						const nextViewState = hasLocalViewState
627							? { ...restoredState, ...currentState }
