    annotations: {
      readOnlyHint: false,
      destructiveHint: false,
      openWorldHint: false,
      idempotentHint: true,
      title: 'Save Lobu app state',
    },
    authorizationReadOnly: true,
    securityScopes: ['mcp:read'],
    mcpMeta: { ui: { visibility: ['app'] } },
    audit: false,
    handler: saveMcpAppState,
  },
];

