172	export async function storeMcpAppResultSnapshot(args: {
173		ctx: ToolContext;
174		toolCallId: unknown;
175		bindingCapability?: unknown;
176		toolName: string;
177		data: UnknownRecord;
178	}): Promise<boolean> {
179		const identity = snapshotIdentity(args.ctx, args.toolCallId);
180		if (
181			!identity ||
182			!args.toolName ||
183			args.toolName.length > TOOL_NAME_MAX_LENGTH
184		)
185			return false;
186		const bindingCapability = normalizeMcpAppToolCallId(args.bindingCapability);
187		const data = displaySafeMcpAppResult(args.data);
188		if (!isRecord(data)) return false;
189		const serialized = serializeSnapshot({
190			version: 1,
191			toolName: args.toolName,
192			data,
193			viewState: {},
194			...(bindingCapability
195				? { bindingKey: hashIdentity(bindingCapability) }
196				: {}),
197		});
198		if (!serialized) return false;
199	
200		const sql = getDb();
201		const collided = await sql.begin(async (tx) => {
202			const [stored] = await tx<{ collided: boolean }>`
203				INSERT INTO public.mcp_app_result_snapshots (
204					organization_id, client_id, user_id, conversation_key,
205					tool_call_key, tool_name, body, plaintext_bytes, expires_at
206				) VALUES (
207					${identity.organizationId}, ${identity.clientId}, ${identity.userId},
208					${identity.conversationKey}, ${identity.toolCallKey}, ${args.toolName},
209					${serialized.body}, ${serialized.plaintextBytes},
210					now() + (${MCP_APP_RESULT_RETENTION_DAYS} * interval '1 day')
211				)
212				ON CONFLICT (
213					organization_id, client_id, user_id, conversation_key, tool_call_key
214				) DO UPDATE SET
215					-- A host request ID is not guaranteed to be unique forever. Never let a
216					-- collision replace the historical card with a different result.
217					expires_at = now(),
218					updated_at = now()
219				RETURNING expires_at <= now() AS collided
220			`;
221			await tx`
222				DELETE FROM public.mcp_app_result_snapshots snapshot
223				WHERE snapshot.organization_id = ${identity.organizationId}
224					AND snapshot.client_id = ${identity.clientId}
225					AND snapshot.user_id = ${identity.userId}
226					AND snapshot.conversation_key = ${identity.conversationKey}
227					AND snapshot.tool_call_key NOT IN (
228						SELECT kept.tool_call_key
229						FROM public.mcp_app_result_snapshots kept
230						WHERE kept.organization_id = ${identity.organizationId}
231							AND kept.client_id = ${identity.clientId}
232							AND kept.user_id = ${identity.userId}
233							AND kept.conversation_key = ${identity.conversationKey}
234						ORDER BY kept.updated_at DESC, kept.tool_call_key
235						LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
236					)
237			`;
238			return stored?.collided === true;
239		});
240		if (collided) {
241			logger.warn(
242				{ toolName: args.toolName },
243				"MCP App result snapshot key collision; historical restore disabled",
244			);
245		}
246		return !collided;
247	}
