    58	}
    59	
    60	const isEmbedded = window.parent !== window;
    61	const OPENAI_SET_GLOBALS_EVENT = "openai:set_globals";
    62	
    63	type OpenAiCompatWindow = Window & { openai?: unknown };
    64	type OpenAiSetGlobalsEvent = CustomEvent<{ globals?: unknown }>;
    65	
    66	function openAiCompatTargets(): OpenAiCompatWindow[] {
    67		const ownWindow = window as OpenAiCompatWindow;
    68		if (!isEmbedded) return [ownWindow];
    69		try {
    70			if (window.parent.location.origin === window.location.origin) {
    71				return [ownWindow, window.parent as OpenAiCompatWindow];
    72			}
    73		} catch {
    74			// A cross-origin parent is the standard portable MCP Apps topology.
    75		}
