				<span>
					{data?.title ?? (resultUnavailable ? "Unavailable" : "Loading")}
				</span>
			);
		}
		render(
			<Provider devMock={{ title: "dev" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalled());
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: {},
					_meta: {
						"lobu/mcp-app-snapshot-capability": "rejected-capability",
					},
				});
			}
		});
		expect(await screen.findByText("Unavailable")).toBeInTheDocument();
		bridge.hostContext = {
			toolInfo: { id: "reused-id", tool: { name: "query_sdk" } },
		};
		act(() => {
			for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) {
				handler({ theme: "light" });
			}
		});
		await new Promise((resolve) => setTimeout(resolve, 20));
		expect(screen.getByText("Unavailable")).toBeInTheDocument();
		expect(screen.queryByText("Wrong reused-id snapshot")).not.toBeInTheDocument();
	});
});

